css='''
:root{--ink:#28251e;--muted:#6d675b;--line:#d6cdbd;--gold:#9b772e;--paper:#fffdf8;--bg:#f2eee5}*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.65 Arial,sans-serif}header,main,footer{max-width:1240px;margin:auto}header{padding:62px 48px 34px}.eyebrow{font-size:11px;letter-spacing:.17em;color:#71592a;font-weight:700}h1{font:normal 54px/1.12 Georgia,serif;margin:15px 0 22px;max-width:850px}h2{font:normal 34px/1.2 Georgia,serif;margin:0 0 24px}h3{font:700 21px/1.3 Georgia,serif;margin:30px 0 14px}p{margin:0 0 18px}.lead{font-size:21px;line-height:1.5;max-width:950px;color:#514b40}.status{font-size:13px;color:var(--muted);margin-top:22px}nav{max-width:1240px;margin:auto;display:flex;gap:8px 22px;flex-wrap:wrap;border-block:1px solid var(--line);padding:16px 48px;background:#e9e1d2}nav a{color:#493b25;font-size:13px;text-decoration:none}nav a:hover{text-decoration:underline}main{background:var(--paper);padding:0 48px}section{padding:45px 0;border-bottom:1px solid var(--line);scroll-margin-top:20px}.sectionno{font-size:12px;letter-spacing:.12em;color:var(--gold);margin-bottom:8px;font-weight:bold}.callout{border-left:4px solid var(--gold);background:#f4eddf;padding:22px 24px;margin:26px 0}.anchors{display:grid;grid-template-columns:repeat(4,1fr);gap:24px;margin-top:17px}.anchors b{display:block;font:normal 27px Georgia,serif;margin-bottom:8px}.anchors span{font-size:13px;line-height:1.4;display:block;color:#5b5142}.columns{display:grid;grid-template-columns:1fr 1fr;gap:36px}.scroll{overflow-x:auto;margin:20px 0 24px;border-top:1px solid var(--line)}table{border-collapse:collapse;width:100%;font-size:14px;line-height:1.5}th{background:#e9e1d2;text-align:left;font-weight:700;font-size:12px;letter-spacing:.015em;color:#493b25}td,th{padding:13px 14px;vertical-align:top;border-bottom:1px solid var(--line)}td:first-child,th:first-child{padding-left:12px}tbody tr:nth-child(even){background:#faf7ef}.num{text-align:right;font-variant-numeric:tabular-nums}.total{background:#ede3d1!important;font-weight:bold}.cite{font-size:11px;color:#735a26;white-space:nowrap}a{color:#775721}code{font-size:13px;background:#f0ece3;padding:2px 4px;border-radius:3px}.method{padding-left:24px}.method li{margin-bottom:14px;padding-left:8px}.filters{background:#efe7d8;padding:18px;display:grid;grid-template-columns:2fr 1.3fr 1fr 1fr;gap:12px}.filters label{font-size:12px;color:#5b503f;font-weight:bold}.filters input,.filters select{display:block;width:100%;margin-top:5px;border:1px solid #c3b69f;border-radius:4px;background:#fffdf8;padding:10px 8px;font:13px Arial;color:#28251e}button{border:1px solid #8c754b;border-radius:4px;background:#fffdf8;color:#5c4520;padding:11px;font-weight:bold;cursor:pointer;align-self:end}button:hover{background:#e2d5b9}.table-note{display:flex;justify-content:space-between;gap:20px;font-size:12px;color:var(--muted);padding:12px 2px}.catalog-scroll{max-height:850px;overflow:auto;margin-top:0;position:relative}#items{min-width:1060px}#items th{position:sticky;top:0;z-index:2}#items td:nth-child(1){min-width:180px;width:18%}#items td:nth-child(2){min-width:125px;width:13%}#items td:nth-child(3),#items td:nth-child(4),#items td:nth-child(5){min-width:105px;width:10%;font-variant-numeric:tabular-nums}#items td:nth-child(6){min-width:90px;width:8%;text-align:right}#items td:nth-child(7){min-width:280px}.itemid{font:11px Arial;color:#817565;display:block;margin-bottom:4px}.tag{display:inline-block;border:1px solid #d6c5a4;padding:1px 6px;border-radius:10px;font-size:10px;margin:0 0 5px}.access{font-size:12px;display:block;color:#6c604e}.itemunit{font-size:11px;color:var(--muted);display:block;margin-top:5px}details summary{cursor:pointer;color:#60491e;font-size:12px}details p{font-size:12px;line-height:1.55;margin:10px 0}details .rule{color:#655c4e;white-space:pre-line}.analysis{font-size:13px;margin-bottom:9px}.caution{padding-left:10px;border-left:2px solid #bb9a55}.sources{padding-left:22px;font-size:13px}.sources li{padding:0 0 22px 8px;margin-bottom:12px;border-bottom:1px solid #e5ddcf}footer{padding:26px 48px 55px;font-size:12px;color:var(--muted)}:focus-visible{outline:3px solid #b48a40;outline-offset:3px}@media(max-width:800px){header{padding:34px 22px}h1{font-size:40px}h2{font-size:28px}main{padding:0 22px}nav{padding:15px 22px;gap:8px 16px}.columns{grid-template-columns:1fr;gap:10px}.anchors{grid-template-columns:1fr 1fr}.filters{grid-template-columns:1fr 1fr}.table-note{display:block}.table-note span{display:block}.lead{font-size:18px}}@media print{body{background:white;font-size:11pt}header,main,footer{max-width:none;padding-left:0;padding-right:0}header{padding-top:0}h1{font-size:30pt}h2{font-size:23pt}nav,.filters,.table-note{display:none}section{padding:25px 0}.columns{display:block}.scroll{overflow:visible}table{font-size:9pt}tr{break-inside:avoid}.catalog-scroll{max-height:none;overflow:visible}#items{min-width:0}#items th{position:static}#items td{min-width:0!important}#items td:nth-child(7){width:30%}details p{font-size:8pt}.sources{font-size:9pt}a{text-decoration:none;color:inherit}.anchors{grid-template-columns:repeat(4,1fr)}}
'''
js='''
const DATA=__DATA__;const ITEMS=DATA.itens;let visible=ITEMS.slice();
const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s).normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').toLowerCase();
const fmt=(x,d=2)=>Number(x).toLocaleString('pt-BR',{minimumFractionDigits:d,maximumFractionDigits:d});
function mixed(cp){cp=Math.round(cp);const g=Math.floor(cp/1000);const s=Math.floor(cp%1000/10);const c=cp%10;return [g?g+' PO':'',s?s+' PP':'',c?c+' PC':''].filter(Boolean).join(' ')||'0 PC'}
function price(pr){return $('currency').value==='silver'?fmt(pr)+' PP':$('currency').value==='gold'?fmt(pr/100,4)+' PO':mixed(pr*10)}
for(const [id,key] of [['category','categoria'],['rarity','raridade'],['access','mercado_nome']])for(const x of [...new Set(ITEMS.map(i=>i[key]))].sort((a,b)=>a.localeCompare(b,'pt-BR'))){const o=document.createElement('option');o.value=x;o.textContent=x;$(id).append(o)}
function render(){const q=norm($('search').value);visible=ITEMS.filter(i=>(!q||norm([i.id,i.nome,i.tags.join(' '),i.categoria,i.justificativa,i.ressalva].join(' ')).includes(q))&&(!$('category').value||i.categoria===$('category').value)&&(!$('rarity').value||i.raridade===$('rarity').value)&&(!$('access').value||i.mercado_nome===$('access').value));
 const s=$('sort').value;visible.sort(s==='price'?(a,b)=>a.preco_cobre-b.preco_cobre:s==='price-desc'?(a,b)=>b.preco_cobre-a.preco_cobre:s==='name'?(a,b)=>a.nome.localeCompare(b.nome,'pt-BR'):(a,b)=>a.id.localeCompare(b.id));
 $('count').textContent=visible.length+' de 170 itens';
 $('rows').innerHTML=visible.map(i=>`<tr data-id="${i.id}"><td><span class="itemid">${esc(i.id)}</span><strong>${esc(i.nome)}</strong><span class="itemunit">${esc(i.unidade)}</span></td><td><span class="tag">${esc(i.raridade)}</span><span class="access">${esc(i.mercado_nome)}</span></td><td><strong>${price(i.preco_prata)}</strong></td><td>${price(i.faixa_baixa_prata)}<br>até ${price(i.faixa_alta_prata)}</td><td>${price(i.revenda_prata)}</td><td>${fmt(i.dias_salario_bruto,1)}</td><td><p class="analysis">${esc(i.justificativa)}</p><details><summary>Composição do valor e regra</summary><p><strong>Materiais de referência:</strong> ${esc(i.materiais_estimados)}.</p><p><strong>Suporte comum acabado:</strong> ${price(i.suporte_cobre/10)}.<br><strong>Prêmio especial estimado:</strong> ${price(i.premio_cobre/10)}.</p>${i.ressalva?`<p class="caution">${esc(i.ressalva)}</p>`:''}<p class="rule"><strong>Regra da carta avaliada:</strong>\\n${esc(i.habilidade||'Sem habilidade adicional.')}</p></details></td></tr>`).join('');
 document.querySelector('.catalog-scroll').scrollTop=0;
 if(!visible.length)$('rows').innerHTML='<tr><td colspan="7">Nenhum item corresponde aos filtros.</td></tr>';
}
for(const id of ['search','category','rarity','access','sort','currency'])$(id).addEventListener(id==='search'?'input':'change',render);
$('clear').addEventListener('click',()=>{for(const id of ['search','category','rarity','access'])$(id).value='';$('sort').value='id';render()});
$('csv').addEventListener('click',()=>{const rows=[['ID','Item','Unidade','Compra (prata)','Compra (ouro)','Faixa baixa (prata)','Faixa alta (prata)','Revenda (prata)','Diárias brutas','Acesso','Justificativa'],...visible.map(i=>[i.id,i.nome,i.unidade,i.preco_prata,i.preco_ouro,i.faixa_baixa_prata,i.faixa_alta_prata,i.revenda_prata,i.dias_salario_bruto,i.mercado_nome,i.justificativa])];const csv='\\ufeff'+rows.map(r=>r.map(v=>'"'+(typeof v==='number'?v.toLocaleString('pt-BR',{useGrouping:false,maximumFractionDigits:8}):String(v)).replace(/"/g,'""')+'"').join(';')).join('\\r\\n');const u=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=u;a.download='Sistema21_Precos_Selecao_v01.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)});
render();
'''.replace('__DATA__',json.dumps(M,ensure_ascii=False).replace('</','<\\/'))
document='<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sistema 21 — estudo econômico e 170 preços propostos</title><style>'+css+'</style></head><body>'+body+'<script>'+js+'</script></body></html>'
target=OUT/'Estudo_Economia_e_Precos_v01.html';target.write_text(document,encoding='utf-8')
(OUT/'relatorio_script_check.js').write_text(js,encoding='utf-8')
print(json.dumps({'html':str(target),'bytes':target.stat().st_size,'itens':len(items),'categorias':len(groups),'fontes':len(sources)},ensure_ascii=False))
